class LRUCache:

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.map = {}
        self.od = OrderedDict()


    def get(self, key: int) -> int:
        if key in self.map:
            self.od.move_to_end(key)
            return self.map[key]
        else:

            return -1


    def put(self, key: int, value: int) -> None:
        if key in self.map:
            self.map[key] = value
            self.od.move_to_end(key)

            return None
        if len(self.map) < self.capacity:
            self.map[key] = value
            self.od[key] = value
        else:
            x, y = self.od.popitem(last=False)
            self.map.pop(x) 
            self.map[key] = value
            self.od[key] = value  



