class Solution:
    def backtrack(self, total, i, nums, goal, map):
        if total > goal:
            return None
        if total == goal:
            return total
        if (i, total) in map:
            return map[(i, total)]
        i = i + 1
        if i > len(nums) - 1:
            return None
        map[(i, total)] = self.backtrack(total, i, nums, goal, map)
        y = map[(i, total)] 
        map[(i, total+nums[i])] = self.backtrack(total + nums[i],i, nums, goal, map)
        z = map[(i, total+nums[i])]
        if y is not None:
            return y
        else:
            return z



    def canPartition(self, nums: list[int]) -> bool:
        total = 0
        for x in nums:
            total += x
        total = total/2
        map = {}
        num = self.backtrack(0, -1, nums, total, map)
        if num == total:
            return True
        return False

class Solution:
    def minCost(self, n: int, cuts: list[int]) -> int:
        rdp = {}
        def dfs(l, r):
            if r-l == 1:
                return 0
            if (l, r) in rdp:
                return rdp[(l, r)]

            res = 100000000
            for c in cuts:
                if l < c < r:
                    res = min(res, (r-l) + dfs(l, c) + dfs(c, r))
            if res == 100000000: 
                res = 0
            rdp[l, r] = res
            return res
        return dfs(0, n)

